Lemma le4_bytes : forall z, le4 (wz z) =
  [Z_to_bv 8 (bv_unsigned (wz z)); Z_to_bv 8 (bv_unsigned (wz z) ≫ 8);
   Z_to_bv 8 ((bv_unsigned (wz z) ≫ 8) ≫ 8); Z_to_bv 8 (((bv_unsigned (wz z) ≫ 8) ≫ 8) ≫ 8)].
Proof. intros z. reflexivity. Qed.

Lemma b8_byte1 : forall f, 0 <= f < 2^64 -> Z_to_bv 8 (bv_unsigned (wz f) ≫ 8) = b8 ((f / 256) mod 256).
Proof.
  intros f Hf. unfold b8, wz. rewrite unsigned_lit by lia. apply bv_eq.
  rewrite !Z_to_bv_unsigned. unfold bv_wrap, bv_modulus. change (2 ^ Z.of_N 8) with 256.
  rewrite Z.shiftr_div_pow2 by lia. change (2^8) with 256. rewrite Z.mod_mod by lia. reflexivity.
Qed.

(* [comment removed for export] *)
Lemma C4_read_byte1 : forall m A f cs, 0 <= f < 2^64 ->
  rw_cells asegs m A (C4 (wz f) :: cs) -> ov_read_bytes asegs m (wa (A + 1)) 1 = Some [b8 ((f / 256) mod 256)].
Proof.
  intros m A f cs Hf [[WF B] _].
  pose proof (bytes_at_ov_read asegs m A _ 1 1 B) as R. change (Z.of_nat 1) with 1 in R.
  rewrite R. 2:{ cbn [cells_bytes cbytes app length]. rewrite length_app, length_le4. lia. }
  cbn [cells_bytes cbytes]. rewrite le4_bytes. cbn [skipn firstn app]. rewrite b8_byte1 by lia. reflexivity.
Qed.

(* [comment removed for export] *)
Lemma pcore_read_f_b1 : forall m P c pad7 pad2,
  rw_cells asegs m P (ParserCoreCells c pad7 pad2) -> 0 <= pc_f c < 2^64 ->
  ov_read_bytes asegs m (wa (P + 77)) 1 = Some [b8 ((pc_f c / 256) mod 256)].
Proof.
  intros m P c pad7 pad2 PC Hf.
  unfold ParserCoreCells in PC.
  lazymatch type of PC with rw_cells _ _ _ (?c1 :: ?c2 :: ?c3 :: ?c4 :: ?c5 :: ?c6 :: ?c7 :: ?c8 :: ?c9 :: ?c10 :: ?c11 :: ?c12 :: ?c13 :: ?rest) =>
    change (c1 :: c2 :: c3 :: c4 :: c5 :: c6 :: c7 :: c8 :: c9 :: c10 :: c11 :: c12 :: c13 :: rest)
      with ([c1; c2; c3; c4; c5; c6; c7; c8; c9; c10; c11; c12; c13] ++ rest) in PC
  end.
  apply (proj1 (rw_cells_app _ _ _ _ _)) in PC. destruct PC as [_ PC]. cbn [cells_size csize Nat.add] in PC.
  replace (P + 77) with (P + Z.of_nat 76 + 1) by lia. eapply C4_read_byte1; [exact Hf | exact PC].
Qed.


(* [comment removed for export] *)
Lemma pcore_cells_read_f_b1 : forall m P pad7 pad2 bh bl ln ln0 sk hl st f,
  rw_cells asegs m P [C8 (wz AVP_PARSER); C1 (b8 bh); CB 7 pad7; C8 (wz bl); C8 (wz ln); C8 (wz ln0); C8 (wz 0); C8 (wz 0);
                    C8 (wz sk); C4 (wz hl); C2 (wz 0); CB 2 pad2; C4 (wz st); C4 (wz f)] -> 0 <= f < 2^64 ->
  ov_read_bytes asegs m (wa (P + 77)) 1 = Some [b8 ((f / 256) mod 256)].
Proof.
  intros. eapply (pcore_read_f_b1 m P (mkPC bh bl ln ln0 sk hl st f) pad7 pad2); [exact H | cbn; lia].
Qed.


(* [comment removed for export] *)
Lemma b8_byte0 : forall f, 0 <= f < 2^64 -> Z_to_bv 8 (bv_unsigned (wz f)) = b8 (f mod 256).
Proof.
  intros f Hf. unfold b8, wz. rewrite unsigned_lit by lia. apply bv_eq.
  rewrite !Z_to_bv_unsigned. unfold bv_wrap, bv_modulus. change (2 ^ Z.of_N 8) with 256. rewrite Z.mod_mod by lia. reflexivity.
Qed.
Lemma C4_read_byte0 : forall m A f cs, 0 <= f < 2^64 ->
  rw_cells asegs m A (C4 (wz f) :: cs) -> ov_read_bytes asegs m (wa A) 1 = Some [b8 (f mod 256)].
Proof.
  intros m A f cs Hf [[WF B] _].
  pose proof (bytes_at_ov_read asegs m A _ 0 1 B) as R. rewrite Z.add_0_r in R.
  rewrite R. 2:{ cbn [cells_bytes cbytes app length]. rewrite length_app, length_le4. lia. }
  cbn [cells_bytes cbytes]. rewrite le4_bytes. cbn [skipn firstn app]. rewrite b8_byte0 by lia. reflexivity.
Qed.
Lemma pcore_cells_read_f_b0 : forall m P pad7 pad2 bh bl ln ln0 sk hl st f,
  rw_cells asegs m P [C8 (wz AVP_PARSER); C1 (b8 bh); CB 7 pad7; C8 (wz bl); C8 (wz ln); C8 (wz ln0); C8 (wz 0); C8 (wz 0);
                    C8 (wz sk); C4 (wz hl); C2 (wz 0); CB 2 pad2; C4 (wz st); C4 (wz f)] -> 0 <= f < 2^64 ->
  ov_read_bytes asegs m (wa (P + 76)) 1 = Some [b8 (f mod 256)].
Proof.
  intros m P pad7 pad2 bh bl ln ln0 sk hl st f PC Hf.
  lazymatch type of PC with rw_cells _ _ _ (?c1 :: ?c2 :: ?c3 :: ?c4 :: ?c5 :: ?c6 :: ?c7 :: ?c8 :: ?c9 :: ?c10 :: ?c11 :: ?c12 :: ?c13 :: ?rest) =>
    change (c1 :: c2 :: c3 :: c4 :: c5 :: c6 :: c7 :: c8 :: c9 :: c10 :: c11 :: c12 :: c13 :: rest)
      with ([c1; c2; c3; c4; c5; c6; c7; c8; c9; c10; c11; c12; c13] ++ rest) in PC
  end.
  apply (proj1 (rw_cells_app _ _ _ _ _)) in PC. destruct PC as [_ PC]. cbn [cells_size csize Nat.add] in PC.
  replace (P + 76) with (P + Z.of_nat 76) by lia. eapply C4_read_byte0; [exact Hf | exact PC].
Qed.

(* [comment removed for export] *)
Lemma f_b1_range : forall f, 0 <= (f / 256) mod 256 < 256.
Proof. intros f. apply Z.mod_pos_bound. lia. Qed.

(* [comment removed for export] *)
Lemma f_b1_testbit : forall f k, 0 <= f -> 0 <= k < 8 ->
  Z.testbit ((f / 256) mod 256) k = Z.testbit f (k + 8).
Proof.
  intros f k Hf Hk. change 256 with (2^8). rewrite <- Z.shiftr_div_pow2 by lia.
  rewrite <- Z.land_ones by lia. rewrite Z.land_spec. rewrite Z.ones_spec_low by lia.
  rewrite Bool.andb_true_r. rewrite Z.shiftr_spec by lia. reflexivity.
Qed.

