(* [comment removed for export] *)
Lemma land_pow2_testbit : forall x k, 0 <= k ->
  Z.land x (2^k) = if Z.testbit x k then 2^k else 0.
Proof.
  intros x k Hk. apply Z.bits_inj'. intros n Hn.
  rewrite Z.land_spec. rewrite Z.pow2_bits_eqb by lia.
  destruct (Z.eqb_spec k n) as [<-|NE].
  - destruct (Z.testbit x k) eqn:T; [rewrite Z.pow2_bits_true by lia; reflexivity | rewrite Z.bits_0; reflexivity].
  - rewrite Bool.andb_false_r. destruct (Z.testbit x k); [rewrite Z.pow2_bits_false by lia| rewrite Z.bits_0]; reflexivity.
Qed.

Lemma pow2_lor : forall j k, 0 <= j -> 0 <= k -> j <> k -> 2^j + 2^k = Z.lor (2^j) (2^k).
Proof.
  intros j k Hj Hk NE.
  assert (D : Z.land (2^j) (2^k) = 0) by (rewrite land_pow2_testbit, Z.pow2_bits_false by lia; reflexivity).
  rewrite <- Z.lxor_lor by exact D. rewrite <- Z.add_nocarry_lxor by exact D. reflexivity.
Qed.

Lemma land_mask2 : forall x j k, 0 <= j -> 0 <= k -> j <> k ->
  Z.land x (2^j + 2^k) = (if Z.testbit x j then 2^j else 0) + (if Z.testbit x k then 2^k else 0).
Proof.
  intros x j k Hj Hk NE.
  rewrite (pow2_lor j k) by lia.
  rewrite Z.land_lor_distr_r. rewrite !land_pow2_testbit by lia.
  destruct (Z.testbit x j), (Z.testbit x k); rewrite ?Z.lor_0_l, ?Z.lor_0_r; first [reflexivity | symmetry; apply pow2_lor; lia | lia].
Qed.

(* [comment removed for export] *)
Lemma land_f_1 : forall f, Z.land f 1 = if Z.testbit f 0 then 1 else 0.
Proof. intros f. change 1 with (2^0) at 1. rewrite land_pow2_testbit by lia. reflexivity. Qed.
Lemma land_f_1024 : forall f, Z.land f 1024 = if Z.testbit f 10 then 1024 else 0.
Proof. intros f. change 1024 with (2^10). rewrite land_pow2_testbit by lia. reflexivity. Qed.
Lemma land_f_2048 : forall f, Z.land f 2048 = if Z.testbit f 11 then 2048 else 0.
Proof. intros f. change 2048 with (2^11). rewrite land_pow2_testbit by lia. reflexivity. Qed.
Lemma land_f_2064 : forall f, Z.land f 2064 = (if Z.testbit f 4 then 16 else 0) + (if Z.testbit f 11 then 2048 else 0).
Proof. intros f. change 2064 with (2^4 + 2^11). rewrite land_mask2 by lia. reflexivity. Qed.
Lemma land_f_10240 : forall f, Z.land f 10240 = (if Z.testbit f 11 then 2048 else 0) + (if Z.testbit f 13 then 8192 else 0).
Proof. intros f. change 10240 with (2^11 + 2^13). rewrite land_mask2 by lia. reflexivity. Qed.
(* [comment removed for export] *)
Lemma land_fb1_4 : forall f, 0 <= f -> Z.land ((f / 256) mod 256) 4 = if Z.testbit f 10 then 4 else 0.
Proof. intros f Hf. change 4 with (2^2). rewrite land_pow2_testbit by lia. rewrite f_b1_testbit by lia. reflexivity. Qed.
Lemma land_fb1_12 : forall f, 0 <= f ->
  Z.land ((f / 256) mod 256) 12 = (if Z.testbit f 10 then 4 else 0) + (if Z.testbit f 11 then 8 else 0).
Proof. intros f Hf. change 12 with (2^2 + 2^3). rewrite land_mask2 by lia. rewrite !f_b1_testbit by lia. reflexivity. Qed.
Lemma land_fb0_64 : forall f, 0 <= f -> Z.land (f mod 256) 64 = if Z.testbit f 6 then 64 else 0.
Proof.
  intros f Hf. change 64 with (2^6) at 1. rewrite land_pow2_testbit by lia.
  change 256 with (2^8). rewrite <- Z.land_ones by lia. rewrite Z.land_spec, Z.ones_spec_low by lia.
  rewrite Bool.andb_true_r. reflexivity.
Qed.
