Lemma win_byte : forall m it0 bs p, bytes_at asegs m it0 bs -> it0 <= p < it0 + Z.of_nat (length bs) ->
  exists b, nth_error bs (Z.to_nat (p - it0)) = Some b.
Proof.
  intros m it0 bs p WIN Hp. destruct (nth_error bs (Z.to_nat (p - it0))) as [b|] eqn:N; [exists b; reflexivity|].
  apply nth_error_None in N. lia.
Qed.


(* [comment removed for export] *)
Lemma win_suffix : forall m it0 bs q, bytes_at asegs m it0 bs -> it0 <= q <= it0 + Z.of_nat (length bs) ->
  bytes_at asegs m q (skipn (Z.to_nat (q - it0)) bs) /\ q + Z.of_nat (length (skipn (Z.to_nat (q - it0)) bs)) = it0 + Z.of_nat (length bs).
Proof.
  intros m it0 bs q WIN Hq.
  rewrite <- (firstn_skipn (Z.to_nat (q - it0)) bs) in WIN. apply bytes_at_app in WIN. destruct WIN as [_ W2].
  rewrite firstn_length_le in W2 by lia. replace (it0 + Z.of_nat (Z.to_nat (q - it0))) with q in W2 by lia.
  split; [exact W2|]. rewrite length_skipn. lia.
Qed.

Lemma tab_byte : forall (T : list Z) c, length T = 256%nat -> 0 <= c < 256 ->
  nth_error (map (fun z => Z_to_bv 8 z) T) (Z.to_nat c) = Some (Z_to_bv 8 (nth (Z.to_nat c) T 0)).
Proof.
  intros T c LT Hc. rewrite nth_error_map.
  destruct (nth_error T (Z.to_nat c)) as [v|] eqn:N.
  - cbn. f_equal. f_equal. symmetry. apply nth_error_nth. exact N.
  - apply nth_error_None in N. lia.
Qed.

