(* [comment removed for export] *)
Lemma unhex_load : forall c, 0 <= c < 256 -> zxb (Z_to_bv 8 (nth (Z.to_nat c) TAB_UNHEX 0)) = wz (unhexb c).
Proof.
  intros c Hc. unfold zxb, wz, unhexb, unhex. rewrite (nth_indep _ 0 (-1)) by (rewrite len_UNHEX; lia). reflexivity.
Qed.



