End HCW.

(* [comment removed for export] *)
(* [comment removed for export] *)
Ltac win_load q :=
  lazymatch goal with WIN : bytes_at _ ?mx ?it0 ?bs |- evt _ _ _ =>
    let b := fresh "b" in let N := fresh "N" in let RD := fresh "RD" in let BR := fresh "BR" in
    destruct (win_byte _ _ _ q WIN ltac:(lia)) as [b N];
    pose proof (zb_range b) as BR; unfold zb in BR;
    pose proof (u8ro_read asegs _ it0 bs (q - it0) b (Z_to_bv 64 q) WIN N ltac:(lia) ltac:(symmetry; apply wa_of_Z_to_bv; lia)) as RD;
    step; clear RD; change (zxb b) with (Z_to_bv 64 (zb b)); fold (zb b) in BR
  end.

(* [comment removed for export] *)
Ltac tab_load TBL TABB TAB LEN c base :=
  let TB := fresh "TB" in let RD := fresh "RD" in
  lazymatch goal with MI : mem_inv _ ?mx |- _ =>
    pose proof (TBL mx MI) as TB;
    pose proof (u8ro_read asegs mx base TABB c (Z_to_bv 8 (nth (Z.to_nat c) TAB 0)) (Z_to_bv 64 (base + c)) TB
                 (tab_byte TAB c LEN ltac:(lia)) ltac:(lia) ltac:(symmetry; apply wa_of_Z_to_bv; lia)) as RD;
    step; clear RD TB
  end.
Ltac tab_unhex c := tab_load tab_unhex_bytes TABB_UNHEX TAB_UNHEX len_UNHEX c 0x2a140.
